from kit import *

P1 = pred('p1', 'Look at the four models above. Which one shows how blood travels in the human body?',
          ['Model A', 'Model B', 'Model C', 'Model D'], 2,
          'Model C. Blood passes through the heart twice on each full trip: the right side sends it to the lungs, it returns to the left side, and the left side sends it to the body. Model A, a single loop through the lungs and then the body, is the most common wrong model, and it has been recorded even among future teachers (Arnaudin & Mintzes, 1985; Pelaez et al., 2005).')
P2 = pred('p2', 'What color is the blood inside your veins?',
          ['Blue', 'Dark red', 'Purple', 'It has no color until it meets air'], 1,
          'Dark red. Blood is red in every vessel, because red blood cells are full of hemoglobin. Blood with little oxygen is a darker red than blood rich in oxygen, but it is never blue. In one survey, about one in five high school students answered that blood is blue (Beytur & Yalmancı, 2022).')

LESSON = {
    'title': 'Two Circuits, One Loop',
    'desc': 'Lesson 3 of BioInnovate: the pulmonary and systemic circuits, where blood gains and loses oxygen, what color blood really is, and how to predict the path of blood.',
    'sessions': 'Sessions 5 and 6',
    'key': 'Why does blood pass through the heart twice on every trip around the body?',
    'pic_alt': 'Two loops of vessels joined at the heart, one to the lungs and one to the body',
    'parts': {

'know': part([
    ('p', 'This lesson puts the heart and the vessels together. You will follow a single red blood cell all the way around the body and back, and find out why it has to pass through the heart twice. It works toward the General Biology 2 competency on transport and circulation (STEM_BIO11/12-IVa-h-1).'),
    ('h3', 'By the end of this lesson, you can:'),
    ('steps', [
        'trace the path of blood through the heart, the lungs and the body in the correct order;',
        'compare the pulmonary circuit with the systemic circuit;',
        'explain where blood gains and loses oxygen, and what color blood really is;',
        'predict where blood goes next from any point in the circulation.']),
    ('h3', 'How to work through the lesson'),
    ('list', [
        '**Session 5** (about one hour): Parts 1 to 4, then Readings 1 and 2 of Part 5.',
        '**Session 6** (about one hour): Readings 3 to 5, then Parts 6 to 9.',
        'Answer every question before you move on, and select any word with a dotted underline to see what it means.',
        'Your work is saved on this device as you go.']),
]),

'pre': part([
    pre(1, 'q1', 'Which chamber pumps blood into the pulmonary circuit?',
        ['Right atrium', 'Right ventricle', 'Left atrium', 'Left ventricle'], 1, 'Reading 1'),
    pre(2, 'q2', 'What do the pulmonary veins carry?',
        ['Oxygen-poor blood to the right atrium', 'Oxygen-rich blood to the left atrium', 'Oxygen-poor blood to the lungs', 'Oxygen-rich blood to the body'], 1, 'Reading 2'),
    pre(3, 'q3', 'How many times does blood pass through the heart on one full trip around the body?',
        ['Once', 'Twice', 'Three times', 'Four times'], 1, 'Reading 1'),
    pre(4, 'q4', 'What color is blood that carries little oxygen?',
        ['Blue', 'Purple', 'Dark red', 'Bright red'], 2, 'Reading 4'),
    pre(5, 'q5', 'Carbon dioxide made in a muscle of your toe leaves the body through the',
        ['skin of the foot', 'kidneys', 'lungs', 'heart'], 2, 'Reading 3'),
], intro='Answer these five questions before you study the lesson. You get one try each, and the lesson tells you where each idea is taught.'),

'in': part([
    ('p', 'In Lesson 1 you saw that the right side of the heart pumps blood to the lungs and the left side pumps blood to the body. In Lesson 2 you followed blood from arteries through capillaries into veins, and saw that capillaries are the only place where substances pass between blood and cells.'),
    ('p', 'In this lesson you join these ideas into one picture: two circuits of vessels, each with its own capillary beds, joined at the heart.'),
    practice(None, 'r1', 'Which vessel carries blood away from the right ventricle?',
             [('Aorta', 'The aorta leaves the left ventricle.'),
              ('Pulmonary trunk', 'Correct. It divides into the two pulmonary arteries, which carry blood to the lungs.'),
              ('Superior vena cava', 'The venae cavae bring blood into the right atrium.')], 1),
], intro='A quick look back at Lessons 1 and 2.'),

'new': part([
    ('p', 'Below are four models of how blood might travel around the body. Each arrow shows the direction of flow. Look at them carefully before you answer.'),
    sim('models', 'Four possible models of the path of blood. Only one is correct.', static=True),
    ('p', 'These two questions are not scored. You will answer them again in Part 7.'),
    P1, P2,
], intro='Four models, and two predictions.'),

'is': part([
    reading(1, 5, 'Two circuits joined at the heart', [
        ('p', 'Humans have [[double circulation]]. Blood flows through two circuits of vessels that are joined at the heart. The [[pulmonary circuit]] carries blood from the right ventricle to the lungs and back to the left atrium. The [[systemic circuit]] carries blood from the left ventricle to all the other tissues of the body and back to the right atrium (Betts et al., 2022, Section 19.1).'),
        ('p', 'The two circuits are connected one after the other. All the blood that goes through one circuit must then go through the other. So on one full trip around the body, blood passes through the heart twice: once through the right side on its way to the lungs, and once through the left side on its way to the body.'),
        ('p', 'Follow one red blood cell. It leaves the left ventricle through the aorta, travels through arteries to a capillary bed in, say, a leg muscle, and gives up oxygen there. It returns through veins and a vena cava to the right atrium, drops into the right ventricle, and is pumped through a pulmonary artery to the lungs. In a lung capillary it picks up oxygen. It returns through a pulmonary vein to the left atrium and drops into the left ventricle, ready to start again.'),
        ('p', 'Why go back to the heart in between? Blood loses most of its pressure as it squeezes through the lung capillaries. In a fish, blood goes straight from the gills to the body at this low pressure. In humans, the blood returns to the left ventricle, which gives it a second, stronger push. This lets blood reach every tissue quickly, even the brain at the top of the body.'),
        sim('circuit', 'Double circulation, drawn as a simplified diagram. The lungs and the body tissues are each shown as one block of capillaries. Follow the red blood cell around one full trip.',
            [('Use “Next stop” to follow the cell for one full trip. How many stops does it make?', 'Ten: left ventricle, aorta, body capillaries, venae cavae, right atrium, right ventricle, pulmonary arteries, lung capillaries, pulmonary veins and left atrium.'),
             ('How many times does the cell pass through the heart in one full trip?', 'Twice: once through the right side and once through the left side.'),
             ('At which two stops does the oxygen level of the blood change?', 'In the body capillaries, where it falls, and in the lung capillaries, where it rises.')]),
        check('c1', 'A red blood cell is in the aorta. How many times must it pass through the heart before it reaches a capillary in the lungs?',
              [('None', 'From the aorta, blood goes to the body, not to the lungs. It must return to the heart first.'),
               ('Once', 'Correct. Aorta → body capillaries → veins → right atrium → right ventricle → pulmonary artery → lung capillaries.'),
               ('Twice', 'It passes through the right side of the heart only once on the way to the lungs.')], 1),
    ]),
    reading(2, 5, 'Comparing the two circuits', [
        ('p', 'The pulmonary circuit is short. It only has to reach the lungs, which sit right beside the heart, and its vessels offer little resistance. The right ventricle therefore needs only a low pressure to push blood through it. This also protects the thin walls of the lung capillaries, which would leak at high pressure.'),
        ('p', 'The systemic circuit is long. It reaches every organ from the scalp to the toes, so its resistance is much higher, and the left ventricle must produce a much higher pressure. This is the reason for the thick wall of the left ventricle that you saw in Lesson 1.'),
        ('p', 'In one way the circuits are exactly equal: each minute they carry the same volume of blood. Because they are joined one after the other, whatever the right ventricle pumps must come back to the left side, and whatever the left ventricle pumps must come back to the right side. If one side pumped less than the other, blood would build up behind it.'),
        ('p', 'The heart muscle does not take oxygen from the blood inside its chambers. It has its own vessels, the [[coronary arteries]], which branch from the aorta just above the aortic valve and spread over the surface of the heart. Coronary veins return the blood to the right atrium. This coronary circulation is part of the systemic circuit (Betts et al., 2022, Section 19.1).'),
        table('Table 3.1. The pulmonary circuit and the systemic circuit (Betts et al., 2022, Sections 19.1 and 20.5)', ['Feature', 'Pulmonary circuit', 'Systemic circuit'], [
            ['Pump', 'right ventricle', 'left ventricle'],
            ['Blood goes to', 'the lungs', 'every other tissue, including the heart muscle'],
            ['Blood returns to', 'the left atrium', 'the right atrium'],
            ['The arteries carry', 'oxygen-poor blood', 'oxygen-rich blood'],
            ['The veins carry', 'oxygen-rich blood', 'oxygen-poor blood'],
            ['Length and resistance', 'short, low resistance', 'long, high resistance'],
            ['Pressure from the ventricle', 'lower', 'much higher'],
            ['Volume pumped each minute', 'the same in both circuits', 'the same in both circuits'],
            ['In the capillaries, blood', 'gains oxygen and loses carbon dioxide', 'loses oxygen and gains carbon dioxide']]),
        check('c2', 'Compare the blood in a pulmonary artery with the blood in the aorta at the same moment. Which statement is correct?',
              [('Both carry oxygen-rich blood at the same pressure.', 'Pulmonary arteries carry oxygen-poor blood, and at a lower pressure.'),
               ('The pulmonary artery carries oxygen-poor blood at lower pressure. The aorta carries oxygen-rich blood at higher pressure.', 'Correct. Different blood, different pressure, but the same volume each minute.'),
               ('The pulmonary artery carries more blood each minute.', 'Both circuits carry the same volume each minute.')], 1),
    ]),
    ('session', 'This is the end of Session 5. In Session 6, start with Reading 3.'),
    reading(3, 5, 'Where the blood changes', [
        ('p', 'Blood changes in only two places, and both are capillary beds. In the lungs, each capillary runs along the wall of a tiny air sac. The air in the sac is rich in oxygen and the blood arriving from the right ventricle is poor in it, so oxygen moves into the blood by [[diffusion]]. Carbon dioxide moves the other way, from the blood into the air, and leaves the body when you breathe out (Clark et al., 2018, Section 39.2).'),
        ('p', 'In the body tissues the gradients are reversed. Working cells use oxygen and make carbon dioxide. So in the body capillaries, oxygen diffuses out of the blood into the cells, and carbon dioxide diffuses from the cells into the blood.'),
        ('p', 'Most of the oxygen in blood is carried by [[hemoglobin]], a protein packed inside red blood cells. Hemoglobin picks up oxygen in the lungs, where there is plenty, and releases it in the tissues, where there is little.'),
        ('p', 'The heart itself does not change the blood. Blood passing through the chambers leaves with the same amount of oxygen it brought in. The right side of the heart only ever holds oxygen-poor blood and the left side only ever holds oxygen-rich blood, because the septum keeps them apart.'),
        sim('exchange', 'Gas exchange in a lung capillary and in a body capillary. The arrows show which way oxygen and carbon dioxide diffuse.', static=True),
        check('c3', 'A brain cell releases carbon dioxide into the blood. Which route does that carbon dioxide take to leave the body?',
              [('Brain capillary → artery → aorta → left ventricle → lungs', 'Blood leaves the brain through veins, not arteries, and returns to the right side of the heart.'),
               ('Brain capillary → vein → superior vena cava → right atrium → right ventricle → pulmonary artery → lung capillary → air', 'Correct. It returns to the right side of the heart, which pumps it to the lungs.'),
               ('Brain capillary → vein → left atrium → left ventricle → aorta → lungs', 'Veins from the body empty into the right atrium, not the left.')], 1),
    ]),
    reading(4, 5, 'What color is blood?', [
        ('p', 'The diagrams in this module, like those in most textbooks, use red for oxygen-rich blood and blue for oxygen-poor blood. The colors are a code that makes the two kinds of blood easy to tell apart. They are not the real colors of blood.'),
        ('p', 'Human blood is always red, because red blood cells are full of hemoglobin. When hemoglobin carries a lot of oxygen, the blood is bright red. When it has given up much of its oxygen, the blood is a darker red. Blood drawn from a vein into a sealed tube is dark red, not blue. It never turns blue anywhere in the body (Beytur & Yalmancı, 2022).'),
        {'type': 'blood'},
        ('p', 'Then why do the veins under your skin look bluish? The answer is in the skin, not in the blood. Red light travels deeper into skin than blue light. Over a vein, much of the red light that reaches the vein is absorbed by the blood, so less red light comes back to your eyes than from the skin beside it. Blue light does not reach as deep, so it comes back about equally from both. Next to the skin around it, the vein looks bluish, even though the blood inside is dark red (Kienle et al., 1996).'),
        ('p', 'A second caution about diagram colors. Red and blue show the two kinds of blood. They do not mean that one half of your body has oxygen-rich blood and the other half has oxygen-poor blood. Every organ, on both sides of the body, receives oxygen-rich blood in its arteries and returns oxygen-poor blood in its veins.'),
        sim('veins', 'What you see through the skin, and what the blood really looks like. Based on Kienle et al. (1996).', static=True),
        check('c4', 'A nurse draws blood from a vein in a patient’s arm into a sealed tube. What color is the blood in the tube?',
              [('Blue, because it has little oxygen', 'Blood is never blue. Hemoglobin with little oxygen is dark red.'),
               ('Dark red', 'Correct. Venous blood carries less oxygen, so it is a darker red than arterial blood.'),
               ('Blue at first, then red when it meets air', 'The tube is sealed, and the blood was red before it left the vein.')], 1),
    ]),
    reading(5, 5, 'Predicting where blood goes next', [
        ('p', 'Once you know the plan of the circulation, you can predict where anything in the blood will go: a medicine, a gas, or a blood clot. Two rules do most of the work.'),
        ('list', [
            '**Rule 1.** After any capillary bed, blood returns to the heart before it reaches the next capillary bed. Lung capillaries are always followed by the left side of the heart, and body capillaries are always followed by the right side.',
            '**Rule 2.** Blood from the body always enters the right atrium. Blood from the lungs always enters the left atrium.']),
        ('p', 'Example: a nurse injects a medicine into a vein in the arm. The medicine travels in the vein to the superior vena cava, enters the right atrium, then the right ventricle, and is pumped through a pulmonary artery to the lung capillaries. Only after it returns to the left side of the heart is it pumped through the aorta to the rest of the body. So the first capillary bed the medicine reaches is in the lungs, not in the arm or the brain.'),
        ('p', 'Example: oxygen from the air reaches a muscle in your toe. It enters the blood in a lung capillary, travels in a pulmonary vein to the left atrium and the left ventricle, and is pumped into the aorta. Arteries carry it down the leg to a capillary in the toe, where it diffuses into the muscle cells.'),
        check('c5', 'A person breathes in a medicine as a spray, and it enters the blood in the lungs. Which heart chamber does it reach first?',
              [('Right atrium', 'Blood from the lungs does not go to the right atrium. Use Rule 2.'),
               ('Left atrium', 'Correct. Blood leaving the lung capillaries travels in the pulmonary veins to the left atrium.'),
               ('Right ventricle', 'The right ventricle pumps blood toward the lungs, not away from them.'),
               ('Left ventricle', 'The left ventricle comes after the left atrium.')], 1),
    ]),
], intro='Five short readings. Readings 1 and 2 are for Session 5, and Readings 3 to 5 for Session 6.'),

'more': part([
    act('order', 'order', 'Put the path in order',
        'A red blood cell is in the left atrium. Arrange the steps in the order the cell passes through them. Use the arrow buttons to move a step up or down, then check.',
        {'first': 'Start: the left atrium receives oxygen-rich blood',
         'items': ['Mitral valve', 'Left ventricle', 'Aorta and systemic arteries', 'Capillaries in the body tissues (oxygen leaves the blood)', 'Venae cavae',
                   'Right atrium, then the tricuspid valve', 'Right ventricle', 'Pulmonary arteries', 'Capillaries in the lungs (oxygen enters the blood)', 'Pulmonary veins'],
         'start': [6, 2, 9, 0, 4, 7, 1, 8, 3, 5], 'last': 'End: back in the left atrium'}),
    ('h3', 'Check these ideas'),
    ('p', 'Decide whether you agree with each idea, then see what science says.'),
    idea('i1', 'Blood goes from the heart to the lungs and then straight to the rest of the body.',
         'Blood returns to the heart after the lungs. The left ventricle then pumps it to the body at high pressure. Single-loop pathways like this one have been recorded among learners, including future teachers (Arnaudin & Mintzes, 1985; Pelaez et al., 2005).'),
    idea('i2', 'Blood without oxygen is blue. It turns red when it meets oxygen.',
         'Blood is red in every vessel. Oxygen-poor blood is dark red, and blood drawn from a vein into a sealed tube is dark red, not blue. In one survey, about one in five high school students answered that blood is blue (Beytur & Yalmancı, 2022).'),
    idea('i3', 'The systemic circuit is more important than the pulmonary circuit.',
         'The two circuits are connected one after the other and carry the same volume of blood each minute. Neither can work without the other. This idea has been recorded among learners (Özgür, 2013).'),
    idea('i4', 'Oxygen-rich blood flows in the left half of the body and oxygen-poor blood in the right half.',
         'Red and blue in a diagram show the two kinds of blood and the two sides of the heart, not two halves of the body. Every organ on both sides receives oxygen-rich blood in its arteries and returns oxygen-poor blood in its veins. This idea has been recorded among learners (Özgür, 2013).'),
    ('h3', 'What if?'),
    ('p', 'Use the two rules from Reading 5 to work out each case.'),
    practice(1, 'm1', 'Suppose blood left the lungs and went straight to the body without returning to the heart. What would be the main problem?',
             [('The blood would carry too much oxygen.', 'The amount of oxygen would be the same. Think about the pressure.'),
              ('The blood would reach the body at low pressure and move slowly, because it loses pressure while passing through the lung capillaries.', 'Correct. This is the problem fish have. The second pass through the heart restores the pressure.'),
              ('The blood would turn blue.', 'Blood is never blue.')], 1),
    practice(2, 'm2', 'A hiker climbs a high mountain, where each breath brings in less oxygen. In which vessels does the blood show the lower oxygen level first?',
             [('The venae cavae', 'Blood in the venae cavae has already passed through the body. The change starts where blood picks up oxygen.'),
              ('The pulmonary veins', 'Correct. Blood leaving the lungs picks up less oxygen, so the pulmonary veins are the first vessels to carry the lower level.'),
              ('The pulmonary arteries', 'Pulmonary arteries carry blood toward the lungs, before it picks up oxygen.'),
              ('The coronary veins', 'Coronary veins come much later in the path.')], 1),
], intro='Put the path in order, check four common ideas, and work out two “what if” cases.'),

'learned': part([
    ('h3', 'Key ideas'),
    ('list', [
        'Blood follows one continuous path made of two circuits. It passes through the heart twice in each full trip.',
        'Pulmonary circuit: right ventricle → pulmonary arteries → lung capillaries → pulmonary veins → left atrium.',
        'Systemic circuit: left ventricle → aorta and arteries → body capillaries → veins and venae cavae → right atrium.',
        'Blood gains oxygen only in the lung capillaries and gives it up only in the body capillaries. The heart does not change the blood.',
        'The pulmonary arteries carry oxygen-poor blood. The pulmonary veins carry oxygen-rich blood.',
        'Both ventricles pump the same volume. The left ventricle works at a much higher pressure.',
        'Blood is always red: bright red when rich in oxygen, dark red when poor in oxygen. Veins look bluish because of how skin reflects light.']),
    ('h3', 'Think again'),
    ('p', 'Here are your two predictions from Part 4. Look at the four models again, then answer.'),
    sim('models', 'The four models again.', static=True),
    think(P1), think(P2),
], intro='A summary of the lesson, and a second look at your predictions.'),

'do': part([
    task('t1', 'Explain the trip to a younger cousin', [
        'A Grade 5 cousin asks you: “How does the air I breathe get to my toes?” Write an answer in 5 to 8 sentences that a ten-year-old can follow.',
        'Your answer should name the lungs, both sides of the heart and the capillaries in the toe, and should say what happens to the carbon dioxide made in the toe. Use one comparison from everyday life, such as a jeepney route or a delivery rider.'], rows=8),
], intro='Explain double circulation in your own words.'),

'assess': part([
    assess(1, 'a1', 'Which chamber pumps blood into the systemic circuit?',
           [('Right atrium', 'The atria receive blood. They do not pump into a circuit.'),
            ('Right ventricle', 'The right ventricle pumps into the pulmonary circuit.'),
            ('Left atrium', 'The left atrium receives blood from the lungs.'),
            ('Left ventricle', 'Correct. It pumps blood into the aorta.')], 3),
    assess(2, 'a2', 'What do the pulmonary arteries carry?',
           [('Oxygen-rich blood to the body', 'That is the aorta.'),
            ('Oxygen-poor blood from the right ventricle to the lungs', 'Correct. They are arteries because they carry blood away from the heart.'),
            ('Oxygen-rich blood from the lungs to the heart', 'That is the pulmonary veins.'),
            ('Oxygen-poor blood from the body to the heart', 'That is the venae cavae.')], 1),
    assess(3, 'a3', 'A red blood cell leaves the right ventricle. Which chambers does it pass through, in order, before it returns to the right ventricle?',
           [('Left atrium, left ventricle, right atrium', 'Correct. Lungs → left atrium → left ventricle → body → right atrium → right ventricle.'),
            ('Right atrium only', 'It must pass through the lungs and the left side first.'),
            ('Left ventricle, left atrium, right atrium', 'Blood always enters an atrium before a ventricle.'),
            ('Left atrium, right atrium', 'It must also pass through the left ventricle to reach the body.')], 0),
    assess(4, 'a4', 'Why do veins under the skin look bluish?',
           [('The blood inside them is blue.', 'Blood is never blue.'),
            ('Skin reflects red and blue light differently over a vein, so the vein looks bluish next to the skin around it.', 'Correct. The bluish look comes from the skin and light, not from the blood (Kienle et al., 1996).'),
            ('Veins have blue walls.', 'Vein walls are not blue.'),
            ('Veins carry no oxygen at all.', 'Venous blood still carries some oxygen, and it is dark red.')], 1),
    assess(5, 'a5', 'Where does blood change from oxygen-poor to oxygen-rich?',
           [('In the right ventricle', 'The heart does not change the blood.'),
            ('In the capillaries of the lungs', 'Correct. Oxygen diffuses from the air sacs into the blood.'),
            ('In the aorta', 'Blood in the aorta is already oxygen-rich.'),
            ('In the capillaries of the body', 'In the body capillaries, blood loses oxygen.')], 1),
    assess(6, 'a6', 'Why does the left ventricle produce a higher pressure than the right ventricle?',
           [('It pumps more blood each minute.', 'Both ventricles pump the same volume each minute.'),
            ('The systemic circuit is long and has a much higher resistance than the pulmonary circuit.', 'Correct. More resistance needs more pressure to move the same volume.'),
            ('Oxygen-rich blood is heavier.', 'The two kinds of blood weigh about the same.'),
            ('The lungs need high pressure.', 'The lungs need low pressure, or their capillaries would leak.')], 1),
    assess(7, 'a7', 'How does the heart muscle get its oxygen?',
           [('From the blood inside the left ventricle', 'The heart muscle does not take oxygen from the blood in its chambers.'),
            ('From the coronary arteries, which branch from the aorta', 'Correct. The coronary circulation is part of the systemic circuit.'),
            ('Directly from the lungs', 'Oxygen reaches the heart muscle in the blood.'),
            ('From the pulmonary veins', 'The pulmonary veins empty into the left atrium.')], 1),
    assess(8, 'a8', 'Which statement about the volume of blood in the two circuits is correct?',
           [('The systemic circuit carries more blood each minute.', 'They carry the same volume each minute.'),
            ('The pulmonary circuit carries more blood each minute.', 'They carry the same volume each minute.'),
            ('Both circuits carry the same volume each minute, because they are connected one after the other.', 'Correct. If one carried more, blood would build up behind the other.'),
            ('It changes from beat to beat at random.', 'Over each minute, the volumes match.')], 2),
    assess(9, 'a9', 'A medicine is injected into a vein in the leg. Which heart chamber does it reach first?',
           [('Right atrium', 'Correct. Leg veins drain into the inferior vena cava, which empties into the right atrium.'),
            ('Left atrium', 'Blood from the body enters the right atrium.'),
            ('Left ventricle', 'The medicine must pass through the lungs before it reaches the left side.'),
            ('Right ventricle', 'Blood enters an atrium before a ventricle.')], 0),
    assess(10, 'a10', 'Which shows the systemic circuit in the correct order?',
           [('Left ventricle → aorta → body capillaries → veins → right atrium', 'Correct.'),
            ('Right ventricle → aorta → body capillaries → veins → left atrium', 'The aorta leaves the left ventricle, and body veins return to the right atrium.'),
            ('Left ventricle → lungs → body capillaries → right atrium', 'That would be a single loop. Blood returns to the heart after the lungs.'),
            ('Left atrium → aorta → body capillaries → right ventricle', 'Blood leaves the heart from a ventricle and returns to an atrium.')], 0),
    {'type': 'score', 'label': 'Assessment'},
    ('h3', 'Check yourself'),
    ('p', 'Rate how well you can do each target now. If you choose “Partly” or “Not yet”, the module points you to the reading to review.'),
    selfcheck([
        ('I can trace a drop of blood through the heart, lungs and body in the correct order.', ('r1', 'Reading 1')),
        ('I can compare the pulmonary circuit and the systemic circuit.', ('r2', 'Reading 2')),
        ('I can explain where blood gains and loses oxygen.', ('r3', 'Reading 3')),
        ('I can explain what color blood really is, and why veins look bluish.', ('r4', 'Reading 4')),
        ('I can predict where blood goes next from any point in the circulation.', ('r5', 'Reading 5'))]),
    ('p', '**Next:** Lesson 4 explains the pressure that keeps all of this blood moving, and how the body controls it.'),
], intro='Ten questions on the whole lesson. You get one try each, then you see the answer and why.'),
    },
}
